mapper.insert:
INSERT INTO document (
    workspace_id, name, media_type, size_bytes, storage_ref,
    content_hash, parse_status, created_at, updated_at
) VALUES (
    #{workspaceId}, #{name}, #{mediaType}, #{sizeBytes}, #{storageRef},
    #{contentHash}, #{parseStatus}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT 
FROM document
JOIN workspace w ON w.id = document.workspace_id AND w.status = 'ACTIVE'
WHERE document.workspace_id = #{workspaceId}
  AND document.content_hash = #{contentHash}

SELECT FROM document JOIN workspace w ON w.id = document.workspace_id AND w.status = 'ACTIVE'
NOT EXISTS ( SELECT 1 FROM dataset ds WHERE ds.document_id = document.id )
AND document.workspace_id = #{workspaceId}
ORDER BY document.created_at DESC, document.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM document JOIN workspace w ON w.id = document.workspace_id AND w.status = 'ACTIVE'
NOT EXISTS ( SELECT 1 FROM dataset ds WHERE ds.document_id = document.id )
AND document.workspace_id = #{workspaceId}

SELECT FROM document JOIN workspace w ON w.id = document.workspace_id AND w.status = 'ACTIVE' WHERE document.id IN
#{documentId}
ORDER BY document.id

SELECT COUNT(*)
FROM task_document
WHERE document_id = #{documentId}

mapper.insert:
INSERT INTO storage_cleanup_failure (
    resource_type, resource_id, storage_ref, storage_ref_fingerprint,
    operation, status, failure_type, failure_summary, retry_count,
    last_retried_at, resolved_at, created_at, updated_at
) VALUES (
    #{resourceType}, #{resourceId}, #{storageRef}, #{storageRefFingerprint},
    #{operation}, #{status}, #{failureType}, #{failureSummary}, #{retryCount},
    #{lastRetriedAt}, #{resolvedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT 
FROM storage_cleanup_failure

    WHERE status = #{status}

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM storage_cleanup_failure

    WHERE status = #{status}
